    reveal(spec.entails(always(p.implies(tla_forall(a_to_q)))));

    // `spec.entails(x)` means `valid(spec.implies(x))`.
    // So we need to show that for all executions `ex`,
    // `spec.implies(always(...))` holds at `ex`.
    unfold(valid);

    forall |ex: Execution<T>| {
        // `spec.implies(r)` is `spec.satisfied_by(ex) ==> r.satisfied_by(ex)`.
        // We split on whether `spec` holds at `ex`.
        if spec.satisfied_by(ex) {
            // From the premise and the definition of `always`:
            // for each parameter `a`, `spec.entails(always(p.implies(a_to_q(a))))`.
            // Instantiating with this `ex` gives us `always(p.implies(a_to_q(a))).satisfied_by(ex)`.
            forall |a: A| {
                // Use the premise entailment to get satisfaction at `ex`.
                // (This entailment is `valid(spec.implies(...))`, so apply to `ex`.)
                assert(spec.implies(always(p.implies(a_to_q(a)))).satisfied_by(ex));
                assert(always(p.implies(a_to_q(a))).satisfied_by(ex));
            }

            // Now show `always(p.implies(tla_forall(a_to_q))).satisfied_by(ex)`.
            // Unfold `always`.
            forall |i: nat| {
                // Need: `p.implies(tla_forall(a_to_q)).satisfied_by(ex.suffix(i))`.
                // By definition: `p.satisfied_by(ex.suffix(i)) ==> tla_forall(a_to_q).satisfied_by(ex.suffix(i))`.
                // So fix an arbitrary `a` and use the earlier per-`a` property.
                assert(p.implies(tla_forall(a_to_q)).satisfied_by(ex.suffix(i)));

                // To prove the above assertion, we unfold `tla_forall`.
